
-- ============================================================
-- Notifications
-- ============================================================
-- Stores outgoing notifications generated by the release
-- synchronization process. Notifications are processed
-- asynchronously by the Telegram worker.
-- ============================================================

CREATE TABLE notifications (
    -- Unique identifier for each notification.
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- Type of event that generated the notification.
    -- Examples: NewRelease, ReleaseUpdated.
    event_type VARCHAR(30) NOT NULL,

    -- Serialized event data in JSON format.
    -- Contains the information required to build and send
    -- the notification without depending on the original event.
    payload JSONB NOT NULL,

    -- Current processing state of the notification.
    -- Possible values: Pending, Processing, Sent, Failed.
    status VARCHAR(20) NOT NULL DEFAULT 'Pending',

    -- Number of attempts made to send the notification.
    attempts INTEGER NOT NULL DEFAULT 0,

    -- Earliest date and time when the notification can be
    -- processed again. Used for retry scheduling.
    next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- Date and time when the notification was claimed
    -- by a worker for processing.
    -- NULL when the notification is not being processed.
    locked_at TIMESTAMPTZ,

    -- Details of the most recent error encountered
    -- while attempting to send the notification.
    last_error TEXT,

    -- Date and time when the notification was created.
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- Date and time when the notification was successfully sent.
    -- NULL while the notification has not been sent.
    sent_at TIMESTAMPTZ,

    -- Ensures that only supported notification states are stored.
    CONSTRAINT chk_notification_status
        CHECK (status IN ('Pending', 'Processing', 'Sent', 'Failed'))
);

-- ============================================================
-- Indexes
-- ============================================================

-- Optimizes retrieval of pending notifications ordered by
-- their scheduled retry time and creation date.
-- Only indexes notifications currently in Pending status.
CREATE INDEX idx_notifications_pending
    ON notifications (next_attempt_at, created_at)
    WHERE status = 'Pending';

-- ============================================================
-- Table and Column Documentation
-- ============================================================

COMMENT ON TABLE notifications IS
'Stores outgoing notifications generated by the release synchronization process for asynchronous delivery.';

COMMENT ON COLUMN notifications.id IS
'Unique identifier of the notification.';

COMMENT ON COLUMN notifications.event_type IS
'Type of release event that generated the notification, such as NewRelease or ReleaseUpdated.';

COMMENT ON COLUMN notifications.payload IS
'Serialized event data in JSONB format, containing the information required to construct and deliver the notification.';

COMMENT ON COLUMN notifications.status IS
'Current processing state of the notification: Pending, Processing, Sent, or Failed.';

COMMENT ON COLUMN notifications.attempts IS
'Number of delivery attempts made for this notification.';

COMMENT ON COLUMN notifications.next_attempt_at IS
'Date and time from which the notification becomes eligible for processing or retry.';

COMMENT ON COLUMN notifications.locked_at IS
'Date and time when the notification was claimed by a worker for processing. Used to identify abandoned processing attempts and recover notifications that remain in Processing status after an unexpected worker termination.';

COMMENT ON COLUMN notifications.last_error IS
'Details of the most recent error encountered during notification delivery.';

COMMENT ON COLUMN notifications.created_at IS
'Date and time when the notification was initially created.';

COMMENT ON COLUMN notifications.sent_at IS
'Date and time when the notification was successfully delivered. NULL indicates that delivery has not been completed.';
